class Solution {
    unordered_map<int, int> parent;
    int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }
    void unite(int x, int y) {
        int rx = find(x), ry = find(y);
        if (rx != ry) parent[rx] = ry;
    }
public:
    vector<vector<int>> matrixRankTransform(vector<vector<int>>& matrix) {
        int m = matrix.size(), n = matrix[0].size();
        map<int, vector<pair<int, int>>> val_map;
        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) {
                val_map[matrix[r][c]].push_back({r, c});
            }
        }
        vector<vector<int>> rank(m, vector<int>(n, 0));
        vector<int> row_max(m, 0), col_max(n, 0);
        for (auto& [val, cells] : val_map) {
            parent.clear();
            for (auto& [r, c] : cells) {
                if (parent.find(r) == parent.end()) parent[r] = r;
                if (parent.find(c + m) == parent.end()) parent[c + m] = c + m;
                unite(r, c + m);
            }
            unordered_map<int, vector<pair<int, int>>> groups;
            for (auto& [r, c] : cells) {
                groups[find(r)].push_back({r, c});
            }
            for (auto& [root, g] : groups) {
                int mx = 0;
                for (auto& [r, c] : g) {
                    mx = max(mx, max(row_max[r], col_max[c]));
                }
