import java.util.*;

class Solution {
    private Map<Integer, Integer> parent = new HashMap<>();

    private int find(int x) {
        if (parent.get(x) != x) parent.put(x, find(parent.get(x)));
        return parent.get(x);
    }

    private void union(int x, int y) {
        int rx = find(x), ry = find(y);
        if (rx != ry) parent.put(rx, ry);
    }

    public int[][] matrixRankTransform(int[][] matrix) {
        int m = matrix.length, n = matrix[0].length;
        TreeMap<Integer, List<int[]>> valMap = new TreeMap<>();
        for (int r = 0; r < m; ++r) {
            for (int c = 0; c < n; ++c) {
                valMap.computeIfAbsent(matrix[r][c], k -> new ArrayList<>()).add(new int[]{r, c});
            }
        }
        int[][] rank = new int[m][n];
        int[] rowMax = new int[m], colMax = new int[n];
        for (Map.Entry<Integer, List<int[]>> entry : valMap.entrySet()) {
            List<int[]> cells = entry.getValue();
            parent.clear();
            for (int[] p : cells) {
                int r = p[0], c = p[1];
                parent.putIfAbsent(r, r);
                parent.putIfAbsent(c + m, c + m);
                union(r, c + m);
            }
            Map<Integer, List<int[]>> groups = new HashMap<>();
            for (int[] p : cells) {
                groups.computeIfAbsent(find(p[0]), k -> new ArrayList<>()).add(p);
            }
            for (List<int[]> g : groups.values()) {
                int mx = 0;
                for (int[] p : g) {
                    mx = Math.max(mx, Math.max(rowMax[p[0]], colMax[p[1]]));
                }
                mx++;
                for (int[] p : g) {
                    rank[p[0]][p[1]] = mx;
                    rowMax[p[0]] = mx;
                    colMax[p[1]] = mx;
                }
            }
        }
        return rank;
    }
}

