var matrixRankTransform = function(matrix) {
    const m = matrix.length, n = matrix[0].length;
    const valMap = new Map();
    for (let r = 0; r < m; ++r) {
        for (let c = 0; c < n; ++c) {
            const v = matrix[r][c];
            if (!valMap.has(v)) valMap.set(v, []);
            valMap.get(v).push([r, c]);
        }
    }
    const sortedKeys = Array.from(valMap.keys()).sort((a, b) => a - b);
    const rank = Array.from({ length: m }, () => Array(n).fill(0));
    const rowMax = Array(m).fill(0), colMax = Array(n).fill(0);

    for (const val of sortedKeys) {
        const cells = valMap.get(val);
        const parent = new Map();
        function find(x) {
            if (parent.get(x) !== x) parent.set(x, find(parent.get(x)));
            return parent.get(x);
        }
        function union(x, y) {
            const rx = find(x), ry = find(y);
            if (rx !== ry) parent.set(rx, ry);
        }
        for (const [r, c] of cells) {
            if (!parent.has(r)) parent.set(r, r);
            if (!parent.has(c + m)) parent.set(c + m, c + m);
            union(r, c + m);
        }
        const groups = new Map();
        for (const [r, c] of cells) {
            const root = find(r);
            if (!groups.has(root)) groups.set(root, []);
            groups.get(root).push([r, c]);
        }
        for (const g of groups.values()) {
            let mx = 0;
            for (const [r, c] of g) {
                mx = Math.max(mx, Math.max(rowMax[r], colMax[c]));
            }
            mx++;
            for (const [r, c] of g) {
                rank[r][c] = mx;
                rowMax[r] = mx;
                colMax[c] = mx;
            }
        }
    }
    return rank;
};
